package com.bank.structured;

import java.util.concurrent.Callable;

// Independent checks that run concurrently as subtasks. Each returns a result or throws.
public class ApprovalChecks {

    public Callable<String> creditCheck(String account) {
        return () -> { Thread.sleep(80); return "CREDIT:OK(" + account + ")"; };
    }
    public Callable<String> incomeCheck(String account) {
        return () -> { Thread.sleep(60); return "INCOME:OK(" + account + ")"; };
    }
    // This one fails to demonstrate fail-fast cancellation of the siblings.
    public Callable<String> fraudCheck(String account) {
        return () -> { Thread.sleep(40); throw new IllegalStateException("FRAUD flagged " + account); };
    }

    // Equivalent rate providers for the racing (shutdown-on-success) demo.
    public Callable<String> rateProviderFast() {
        return () -> { Thread.sleep(30); return "RATE:1USD=83.10 (fast)"; };
    }
    public Callable<String> rateProviderSlow() {
        return () -> { Thread.sleep(200); return "RATE:1USD=83.12 (slow)"; };
    }
}
