package com.bank.structured;

import java.util.concurrent.StructuredTaskScope;
import java.util.logging.Logger;

public class TransferApprovalService {
    private static final Logger log = Logger.getLogger(TransferApprovalService.class.getName());
    private final ApprovalChecks checks = new ApprovalChecks();

    // FAIL-FAST: all three checks must pass; first failure cancels the others.
    public String approve(String account) throws Exception {
        try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
            var credit = scope.fork(checks.creditCheck(account));   // each on a virtual thread
            var income = scope.fork(checks.incomeCheck(account));
            var fraud  = scope.fork(checks.fraudCheck(account));

            scope.join();              // wait for all OR until one fails
            scope.throwIfFailed();     // rethrow the first failure (cancels the rest)

            // reached only if ALL succeeded
            return credit.get() + " | " + income.get() + " | " + fraud.get();
        }
        // scope close() GUARANTEES every subtask finished/cancelled → no orphans
    }

    // RACE: take the FIRST provider to answer; the slower one is cancelled.
    public String fastestRate() throws Exception {
        try (var scope = new StructuredTaskScope.ShutdownOnSuccess<String>()) {
            scope.fork(checks.rateProviderFast());
            scope.fork(checks.rateProviderSlow());
            scope.join();              // returns as soon as one succeeds
            return scope.result();     // the winning result
        }
    }
}
