package com.bank.structured;

import java.util.logging.Logger;

public class StructuredConcurrencyDemo {
    private static final Logger log = Logger.getLogger(StructuredConcurrencyDemo.class.getName());

    public static void main(String[] args) throws Exception {
        TransferApprovalService service = new TransferApprovalService();

        // Fail-fast: the fraud check fails → credit + income are cancelled automatically.
        try {
            service.approve("SAV2001");    // Rajesh
        } catch (Exception e) {
            log.warning(() -> "approval failed fast: " + e.getCause().getMessage()
                + " (siblings cancelled, nothing orphaned)");
        }

        // Race: fastest rate provider wins, slow one cancelled.
        String rate = service.fastestRate();
        log.info(() -> "winning " + rate + " (slow provider cancelled)");
    }
}
